import { Suspense } from "react";
import { styled } from "styled-components";

import type { IdServiceDeLaMarque } from "@/shared/config/services-de-la-marque";
import { withOpacity } from "@/shared/design-tokens/color";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { media } from "@/shared/design-tokens/media";
import { px } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";
import { vitrine } from "@/shared/design-tokens/vitrine-typo";
import { lazyWithRetry } from "@/shared/utils/lazy-with-retry";

import { Glyphe } from "./Glyphe";
import { NOEUDS_DU_RESEAU } from "./systeme.reseau";

/**
 * La frise des services — la forme du système sous 750 px de scène.
 *
 * Le nœud et le fil du parcours d'une affaire du héros justiciable, repris tels
 * quels : au téléphone, les deux versants se lisent de la même façon. Chaque
 * service se déplie sur sa vignette et ses fiches (`ServiceEnDetail`, chargé à
 * la première ouverture) ; un seul ouvert à la fois.
 *
 * Styles AVANT le composant (règle 18 — TDZ en chunk Vite).
 */

const ServiceEnDetail = lazyWithRetry(() => import("./ServiceEnDetail"));

const NOEUD = px(52);
const FIL = 3;

const Liste = styled.ol`
  position: relative;
  display: flex;
  flex-direction: column;
  gap: ${px(6)};
  margin: 0;
  padding: 0;
  list-style: none;

  &::before {
    content: "";
    position: absolute;
    left: calc(${NOEUD} / 2 + ${px(12)} - ${FIL / 2}px);
    top: calc(${NOEUD} / 2);
    bottom: calc(${NOEUD} / 2);
    width: ${FIL}px;
    border-radius: ${FIL / 2}px;
    background: linear-gradient(180deg, ${nuit.marque}, ${nuit.accent});
  }
`;

const Bascule = styled.button`
  position: relative;
  display: flex;
  align-items: center;
  gap: ${px(16)};
  width: 100%;
  min-height: ${px(56)};
  padding: ${px(6)} ${px(12)};
  border: 0;
  border-radius: ${radius.md};
  background: transparent;
  color: ${nuit.encre};
  text-align: left;
  cursor: pointer;

  &[aria-expanded="true"] {
    background: ${nuit.voileLeger};
  }

  &:focus-visible {
    outline: var(--border-medium) solid ${nuit.focus};
    outline-offset: ${px(2)};
  }
`;

const Noeud = styled.span`
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: ${NOEUD};
  height: ${NOEUD};
  /* Un cercle par son rayon : un glyphe, jamais un texte (règle 17). */
  border-radius: calc(${NOEUD} / 2);
  border: var(--border-thin) solid ${withOpacity(nuit.accent, 0.45)};
  background:
    linear-gradient(${nuit.verre}, ${nuit.verre}),
    ${nuit.fond};
  color: ${nuit.accent};

  svg {
    width: 46%;
    height: 46%;
  }

  [aria-expanded="true"] > & {
    border-color: ${nuit.accent};
  }
`;

const Nom = styled.span`
  flex: 1 1 auto;
  font-size: ${vitrine.cardBody};
  font-weight: 600;
  line-height: 1.3;

  ${media.mobile} {
    font-size: ${vitrine.mobile.cardBody};
  }
`;

const Chevron = styled.span`
  flex: 0 0 auto;
  color: ${nuit.encreDouce};
  transition: transform 0.25s ease;

  [aria-expanded="true"] > & {
    transform: rotate(180deg);
  }

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
`;

const Depli = styled.div`
  position: relative;
  z-index: 1;
  margin: ${px(8)} 0 ${px(12)} ${px(12)};
  padding: ${px(14)};
  border: var(--border-thin) solid ${withOpacity(nuit.accent, 0.25)};
  border-radius: ${radius.lg};
  background: ${withOpacity(nuit.fond, 0.92)};
`;

export function FriseDuSysteme({
  ouvert,
  mouvementReduit,
  onBasculer,
}: {
  ouvert: IdServiceDeLaMarque | null;
  mouvementReduit: boolean;
  onBasculer: (id: IdServiceDeLaMarque) => void;
}) {
  return (
    <Liste aria-label="Les services, un par un">
      {NOEUDS_DU_RESEAU.map((noeud) => {
        const estOuvert = ouvert === noeud.id;
        return (
          <li key={noeud.id} id={`frise-${noeud.id}`}>
            <Bascule
              type="button"
              aria-expanded={estOuvert}
              aria-controls={`frise-detail-${noeud.id}`}
              onClick={() => onBasculer(noeud.id)}
            >
              <Noeud aria-hidden="true">
                <Glyphe trace={noeud.glyphe} />
              </Noeud>
              <Nom>{noeud.libelle}</Nom>
              <Chevron aria-hidden="true">⌄</Chevron>
            </Bascule>
            {estOuvert && (
              <Depli id={`frise-detail-${noeud.id}`}>
                <Suspense fallback={null}>
                  <ServiceEnDetail serviceId={noeud.id} mouvementReduit={mouvementReduit} empile />
                </Suspense>
              </Depli>
            )}
          </li>
        );
      })}
    </Liste>
  );
}
