/**
 * Design System - Media Queries & Responsive Helpers
 *
 * Charte Officielle Juris-Power / MEDIANE
 *
 * Breakpoints standardisés pour toute l'application.
 * Utiliser ces helpers au lieu de hardcoder des @media queries.
 *
 * Usage:
 *   import { media, breakpoints } from '@/shared/design-tokens/media';
 *
 *   const MyComponent = styled.div`
 *     padding: 24px;
 *     ${media.mobile} {
 *       padding: 16px;
 *     }
 *   `;
 */


import { px } from "./scale";

// ============================================
// GLOBAL LAYOUT CONSTANTS
// ============================================

/**
 * CSS zoom factor — LEGACY, kept for backward compatibility.
 * The global `zoom: 0.8` on `<html>` has been removed. All dimensions are now
 * scaled via design tokens (scale.ts). This constant is set to 1 (no zoom).
 *
 * If you find code dividing coordinates by CSS_ZOOM_FACTOR, it can be simplified
 * to use the raw coordinates directly.
 *
 * @deprecated No longer needed — zoom has been removed from globals.css.
 */
export const CSS_ZOOM_FACTOR = 1;

// ============================================
// BREAKPOINTS - Points de rupture en pixels
// ============================================

export const breakpoints = {
  /** 360px - Ultra petit (vieux téléphones, mode paysage) */
  xs: 360,
  /** 480px - Mobile portrait */
  sm: 480,
  /** 640px - Mobile landscape / grand mobile */
  md: 640,
  /** 768px - Tablette portrait */
  lg: 768,
  /** 1024px - Tablette landscape / petit desktop */
  xl: 1024,
  /** 1280px - Desktop standard */
  '2xl': 1280,
  /** 1536px - Grand écran */
  '3xl': 1536,
} as const;

// ============================================
// MEDIA QUERIES - Helpers pour styled-components
// ============================================

/**
 * Media queries desktop-first (max-width)
 * Usage: ${media.mobile} { ... }
 */
export const media = {
  /** < 360px - Ultra petit mobile */
  ultraMobile: `@media (max-width: ${breakpoints.xs - 1}px)`,
  /** < 480px - Mobile portrait */
  mobile: `@media (max-width: ${breakpoints.sm - 1}px)`,
  /** < 640px - Mobile étendu */
  mobileWide: `@media (max-width: ${breakpoints.md - 1}px)`,
  /** < 768px - Tablette portrait et moins */
  tablet: `@media (max-width: ${breakpoints.lg - 1}px)`,
  /** < 1024px - Tablette landscape et moins */
  tabletLandscape: `@media (max-width: ${breakpoints.xl - 1}px)`,
  /** < 1280px - Petit desktop et moins */
  desktop: `@media (max-width: ${breakpoints['2xl'] - 1}px)`,
  /** < 1536px - Desktop standard et moins */
  desktopWide: `@media (max-width: ${breakpoints['3xl'] - 1}px)`,
} as const;

/**
 * Media queries mobile-first (min-width)
 * Usage: ${mediaUp.tablet} { ... }
 */
export const mediaUp = {
  /** >= 360px */
  xs: `@media (min-width: ${breakpoints.xs}px)`,
  /** >= 480px */
  sm: `@media (min-width: ${breakpoints.sm}px)`,
  /** >= 640px */
  md: `@media (min-width: ${breakpoints.md}px)`,
  /** >= 768px */
  lg: `@media (min-width: ${breakpoints.lg}px)`,
  /** >= 1024px */
  xl: `@media (min-width: ${breakpoints.xl}px)`,
  /** >= 1280px */
  '2xl': `@media (min-width: ${breakpoints['2xl']}px)`,
  /** >= 1536px */
  '3xl': `@media (min-width: ${breakpoints['3xl']}px)`,
} as const;

/**
 * Media queries pour ranges (entre deux breakpoints)
 * Usage: ${mediaBetween.tabletOnly} { ... }
 */
export const mediaBetween = {
  /** 480px - 639px : Mobile landscape uniquement */
  mobileOnly: `@media (min-width: ${breakpoints.sm}px) and (max-width: ${breakpoints.md - 1}px)`,
  /** 640px - 767px : Entre mobile et tablette */
  mobileToTablet: `@media (min-width: ${breakpoints.md}px) and (max-width: ${breakpoints.lg - 1}px)`,
  /** 768px - 1023px : Tablette uniquement */
  tabletOnly: `@media (min-width: ${breakpoints.lg}px) and (max-width: ${breakpoints.xl - 1}px)`,
  /** 1024px - 1279px : Petit desktop uniquement */
  smallDesktopOnly: `@media (min-width: ${breakpoints.xl}px) and (max-width: ${breakpoints['2xl'] - 1}px)`,
} as const;

// ============================================
// UTILITIES - Fonctions utilitaires
// ============================================

/**
 * Crée une media query personnalisée
 * @param maxWidth - Largeur maximale en pixels
 */
export const maxWidth = (width: number) => `@media (max-width: ${width}px)`;

/**
 * Crée une media query personnalisée min-width
 * @param minWidth - Largeur minimale en pixels
 */
export const minWidth = (width: number) => `@media (min-width: ${width}px)`;

/**
 * Crée une media query pour un range
 * @param min - Largeur minimale en pixels
 * @param max - Largeur maximale en pixels
 */
export const between = (min: number, max: number) =>
  `@media (min-width: ${min}px) and (max-width: ${max}px)`;

// ============================================
// RESPONSIVE VALUES - Valeurs conditionnelles
// ============================================

/**
 * Génère du CSS responsive pour une propriété
 * Usage:
 *   ${responsive('padding', { base: '24px', tablet: '16px', mobile: '12px' })}
 */
export const responsive = (
  property: string,
  values: {
    base: string;
    desktop?: string;
    tabletLandscape?: string;
    tablet?: string;
    mobileWide?: string;
    mobile?: string;
    ultraMobile?: string;
  }
) => {
  let css = `${property}: ${values.base};`;

  if (values.desktop) {
    css += `${media.desktop} { ${property}: ${values.desktop}; }`;
  }
  if (values.tabletLandscape) {
    css += `${media.tabletLandscape} { ${property}: ${values.tabletLandscape}; }`;
  }
  if (values.tablet) {
    css += `${media.tablet} { ${property}: ${values.tablet}; }`;
  }
  if (values.mobileWide) {
    css += `${media.mobileWide} { ${property}: ${values.mobileWide}; }`;
  }
  if (values.mobile) {
    css += `${media.mobile} { ${property}: ${values.mobile}; }`;
  }
  if (values.ultraMobile) {
    css += `${media.ultraMobile} { ${property}: ${values.ultraMobile}; }`;
  }

  return css;
};

// ============================================
// HIDE/SHOW HELPERS - Affichage conditionnel
// ============================================

/**
 * CSS pour cacher sur mobile
 */
export const hideOnMobile = `
  ${media.tablet} {
    display: none !important;
  }
`;

/**
 * CSS pour afficher uniquement sur mobile
 */
export const showOnMobileOnly = `
  display: none !important;
  ${media.tablet} {
    display: block !important;
  }
`;

/**
 * CSS pour cacher sur desktop
 */
export const hideOnDesktop = `
  ${mediaUp.xl} {
    display: none !important;
  }
`;

// ============================================
// CONTAINER WIDTHS - Largeurs de conteneurs
// ============================================

export const containerWidths = {
  /** base 1200px → 960px - Largeur max standard */
  default: px(1200),
  /** base 800px → 640px - Largeur max étroite (formulaires) */
  narrow: px(800),
  /** base 600px → 480px - Largeur max très étroite (modals) */
  xnarrow: px(600),
  /** base 1400px → 1120px - Largeur max large (dashboards) */
  wide: px(1400),
  /** Pleine largeur avec padding (scaled) */
  fluid: `calc(100% - ${px(32)})`,
  /** Pleine largeur mobile (scaled) */
  fluidMobile: `calc(100% - ${px(24)})`,
} as const;

// ============================================
// MODAL WIDTHS - Largeurs de modals responsive
// ============================================

export const modalWidths = {
  /** Modal petit (confirmations) */
  sm: {
    desktop: px(400),
    mobile: `calc(100vw - ${px(32)})`,
  },
  /** Modal moyen (formulaires simples) */
  md: {
    desktop: px(520),
    mobile: `calc(100vw - ${px(32)})`,
  },
  /** Modal large (formulaires complexes) */
  lg: {
    desktop: px(680),
    mobile: `calc(100vw - ${px(24)})`,
  },
  /** Modal très large (tableaux, previews) */
  xl: {
    desktop: px(900),
    mobile: `calc(100vw - ${px(16)})`,
  },
} as const;

/**
 * Génère le CSS pour une modal responsive
 * Usage: ${responsiveModal('md')}
 */
export const responsiveModal = (size: keyof typeof modalWidths) => `
  width: ${modalWidths[size].desktop};
  max-width: calc(100vw - ${px(32)});

  ${media.tablet} {
    width: ${modalWidths[size].mobile};
    max-width: none;
  }
`;

// ============================================
// ORIENTATION - Détection orientation écran
// ============================================

export const orientation = {
  /** Orientation portrait */
  portrait: '@media (orientation: portrait)',
  /** Orientation paysage */
  landscape: '@media (orientation: landscape)',
  /** Mobile en paysage (hauteur très limitée — navbar + header mangent l'espace) */
  mobileLandscape: '@media (orientation: landscape) and (max-height: 500px)',
} as const;

// ============================================
// INPUT CAPABILITY - Détection type de pointeur
// ============================================

export const inputCapability = {
  /** Appareil tactile sans hover précis (téléphones, tablettes) */
  touch: '@media (hover: none) and (pointer: coarse)',
  /** Souris ou trackpad avec hover précis (desktop) */
  mouse: '@media (hover: hover) and (pointer: fine)',
} as const;

// ============================================
// VIEWPORT TOKENS - Hauteurs dynamiques
// ============================================

/**
 * Tokens CSS pour hauteurs viewport dynamiques.
 *
 * Problème : `100vh` sur iOS Safari inclut l'espace derrière la barre d'adresse.
 * Résultat : les éléments `height: 100vh` sont plus grands que l'écran visible.
 *
 * Solution : utiliser `dvh` (dynamic viewport height) qui s'adapte en temps réel.
 * Fallback `100vh` pour les navigateurs qui ne supportent pas dvh.
 *
 * Usage dans styled-components :
 *   height: ${viewport.fullHeight};
 *   min-height: ${viewport.smallHeight};
 */
export const viewport = {
  /** 100dvh — S'adapte dynamiquement (barre d'adresse show/hide) */
  fullHeight: 'var(--full-vh, 100vh)',
  /** 100svh — Plus petite hauteur (barre d'adresse visible) */
  smallHeight: 'var(--small-vh, 100vh)',
  /** 100lvh — Plus grande hauteur (barre d'adresse masquée) */
  largeHeight: 'var(--large-vh, 100vh)',
} as const;
